def rle_index(metrics, mins, maxs, weights):
    norm = {w: (metrics[w]-mins[w])/(maxs[w]-mins[w]) for w in metrics}
    assert abs(sum(weights.values())-1) < 1e-6
    return sum(weights[w]*norm[w] for w in norm), norm

