import torch
def oac_steer(act, d, U_R, lam=lambda rho: rho, alpha=1.0):
    Pd = U_R @ (U_R.t() @ d)                # 共享成分
    rho = Pd.norm() / (d.norm() + 1e-8)     # 重叠度
    d_cal = d - lam(rho) * Pd               # 自适应去掉多少
    return act - alpha * d_cal / (d_cal.norm() + 1e-8)
